package settings

// Table is complete for surviving settings from the source inventory and the
// approved additions. Operator fields share ControllerCeilings, never an author layer.
func Table() []Rule {
	return []Rule{
		{Key: "operator.run_retention_days", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "disabled", Validation: "nonnegative; newest successful run/output and ledger exceptions survive"},
		{Key: "operator.node_metric_retention_days", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "disabled", Validation: "nonnegative; metric retention is independent of run retention"},
		{Key: "config_path", Resolver: "ConfigPath", Sources: []Source{Flag, Env, Default}, Phase: Startup, Merge: "replace", Zero: "invalid", Validation: "runner --config, then SPARKWING_CONFIG, XDG config directory, then home; other CLI commands have no --config flag"},
		{Key: "home", Resolver: "Home", Sources: []Source{Env, Default}, Phase: Startup, Merge: "replace", Zero: "invalid", Validation: "SPARKWING_HOME then user home/.sparkwing; hidden --home is removed"},
		{Key: "profile", Resolver: "Profile", Sources: []Source{Flag, Run, ProjectPipeline, Default}, Phase: AcceptPlan, Merge: "replace", Zero: "local", Validation: "connection names exist only in the machine file; project profiles always fail"},
		{Key: "args", Resolver: "Args", Sources: []Source{Flag, Run, ProjectPipeline, ProjectDefaults, Code, Default}, Phase: AcceptPlan, Merge: "per_key", Zero: "empty map", Validation: "request flags > schedule host overrides > schedule args > pipeline > defaults > SDK defaults"},
		{Key: "guards", Resolver: "Guards", Sources: []Source{Run, ProjectPipeline, ProjectDefaults, Default}, Phase: AcceptPlan, Merge: "replace", Zero: "empty block", Validation: "where/arg/git tokens only; default branch unresolved fails closed"},
		{Key: "requires", Resolver: "Requires", Sources: []Source{Flag, Run, ProjectPipeline, ProjectDefaults, Code, Default}, Phase: AcceptPlan, Merge: "replace_then_add_job", Zero: "empty list", Validation: "pipeline replaces defaults; job requires add; run requirements and allowed pools always inherited"},
		{Key: "prefers", Resolver: "Prefers", Sources: []Source{Flag, Run, ProjectPipeline, ProjectDefaults, Code, Default}, Phase: AcceptPlan, Merge: "replace", Zero: "empty list", Validation: "one resolved preference list on each job row"},
		{Key: "workers", Resolver: "Workers", Sources: []Source{Flag, Run, Default}, Phase: Intake, Merge: "replace", Zero: "invalid", Validation: "positive; default NumCPU; detached refuses explicit worker flag"},
		{Key: "output", Resolver: "Output", Sources: []Source{Flag, Env, Run, Default}, Phase: Intake, Merge: "replace", Zero: "invalid", Validation: "--sw-output > SPARKWING_LOG_FORMAT; pretty/json/plain; terminal detection default"},
		{Key: "admission_class", Resolver: "AdmissionClass", Sources: []Source{Run, Code, Default}, Phase: AcceptPlan, Merge: "replace", Zero: "invalid", Validation: "inferred only when absent; operator class restrictions checked at acceptance"},
		{Key: "priority", Resolver: "Priority", Sources: []Source{Flag, Run, Code, Default}, Phase: AcceptPlan, Merge: "replace", Zero: "normal", Validation: "--sw-priority beats plan priority; validate declared range and operator ceiling"},
		{Key: "admission", Resolver: "AdmissionPolicy", Sources: []Source{Flag, Machine, Default}, Phase: Startup, Merge: "per_key", Zero: "per_field", Validation: "budget,mode,custom,jev preserve existing admission model; invalid values fail startup"},
		{Key: "toolchain", Resolver: "Toolchain", Sources: []Source{Env, Default}, Phase: Startup, Merge: "replace", Zero: "invalid", Validation: "auto/local only; .sparkwing/go.mod pin remains authoritative"},
		{Key: "debug.pause_timeout", Resolver: "PauseTimeout", Sources: []Source{Run, Machine, Default}, Phase: Intake, Merge: "replace", Zero: "invalid", Validation: "positive duration; invalid does not warn and default"},
		{Key: "machine.box_id", Resolver: "BoxID", Sources: []Source{Machine, Default}, Phase: Startup, Merge: "replace", Zero: "invalid", Validation: "hostname only if unset; unreadable machine file is an error"},
		{Key: "cache", Resolver: "BinaryCache", Sources: []Source{Flag, Machine, Default}, Phase: Startup, Merge: "per_key", Zero: "unbounded", Validation: "max_bytes and max_entries are nonnegative; zero disables only that bound"},
		{Key: "secrets_key", Resolver: "SecretsKey", Sources: []Source{Env, Default}, Phase: Startup, Merge: "independent_current_previous", Zero: "invalid", Validation: "current key env > key file env > config-dir secrets.key; fssecure; previous key independently retained"},
		{Key: "schedule.catch_up", Resolver: "CatchUp", Sources: []Source{Flag, Run, ProjectPipeline, Default}, Phase: AcceptPlan, Merge: "replace", Zero: "invalid", Validation: "host override > schedule catch_up > limits default; refuse below min or above max"},
		{Key: "runner", Resolver: "Runner", Sources: []Source{Flag, Machine, Default}, Phase: Startup, Merge: "per_key", Zero: "per_field", Validation: "max_concurrent defaults one; explicit nonpositive lease/heartbeat/poll fails; limits.CheckRenewal"},
		{Key: "owner_execution", Resolver: "OwnerExecution", Sources: []Source{Run, Default}, Phase: Intake, Merge: "operator", Zero: "unbounded_local_only", Validation: "operator flag > team DB > global DB > profile > limits default; remote six hours by default; no local deadline"},
		{Key: "job.timeout", Resolver: "JobTimeout", Sources: []Source{Run, Code, Default}, Phase: AcceptPlan, Merge: "replace", Zero: "invalid", Validation: "explicit positive author timeout must not exceed operator ceiling; absent inherits execution bound"},
		{Key: "approval.wait", Resolver: "ApprovalWait", Sources: []Source{Run, Code, Default}, Phase: AcceptPlan, Merge: "replace", Zero: "indefinite", Validation: "nonnegative; remote host bounds by owner execution; local/controller-owned waits may be indefinite"},
		{Key: "job.retry", Resolver: "Retry", Sources: []Source{Run, Code, Default}, Phase: AcceptPlan, Merge: "replace", Zero: "no retries", Validation: "integer 0..limits.MaxRetries; application retries separate from disruptions"},
		{Key: "job.memo_ttl", Resolver: "MemoTTL", Sources: []Source{Run, Code, Default}, Phase: AcceptPlan, Merge: "replace", Zero: "invalid", Validation: "positive and at most limits.MemoMaxTTL; refusal never clamp"},
		{Key: "claim_wait", Resolver: "ClaimWait", Sources: []Source{Run, Code, Default}, Phase: AcceptPlan, Merge: "replace", Zero: "invalid", Validation: "positive; queued job also ends at owner deadline where present"},
		{Key: "retention", Resolver: "Retention", Sources: []Source{Flag, TeamDB, GlobalDB, LimitsProfile, Default}, Phase: Startup, Merge: "per_key", Zero: "disabled", Validation: "run and metric days independent; cloud run default 90, self-hosted off; newest success and ledger exceptions"},
		{Key: "idle_poll", Resolver: "IdlePoll", Sources: []Source{Flag, Machine, Default}, Phase: Startup, Merge: "server_advice_floor", Zero: "invalid", Validation: "positive client floor; server advice may widen to limits maximum; never counts as a lease renewal"},
		{Key: "connection", Resolver: "ControllerConnection", Sources: []Source{Flag, Machine, Default}, Phase: Startup, Merge: "replace", Zero: "local", Validation: "explicit profile selects machine connection; local controller endpoint is a lifecycle fact, never dev.env"},
		{Key: "repo_location", Resolver: "RepoLocation", Sources: []Source{Flag, Run, Machine, Default}, Phase: Intake, Merge: "ordered_lookup", Zero: "invalid", Validation: "submitted checkout > parent checkout > registered repo > configured fallback paths; no env or ~/code assumption"},
		{Key: "debug.pause", Resolver: "PauseTargets", Sources: []Source{Flag, Run, Default}, Phase: Intake, Merge: "per_key", Zero: "no pauses", Validation: "--sw-pause-* becomes request data; removed DEBUG_PAUSE env is not read"},
		{Key: "debug", Resolver: "Debug", Sources: []Source{Env, Run, Default}, Phase: Intake, Merge: "replace", Zero: "false", Validation: "SPARKWING_DEBUG; host filters frames consistently"},
		{Key: "publish", Resolver: "Publish", Sources: []Source{Flag, Run, Default}, Phase: Intake, Merge: "replace", Zero: "disabled", Validation: "--publish selects machine profile; local provenance; failure cannot fail local run"},
		{Key: "cache_from", Resolver: "CacheFrom", Sources: []Source{Flag, Run, Machine, Default}, Phase: Intake, Merge: "replace", Zero: "disabled", Validation: "--sw-cache-from > run.cache_from; read-only repo-bound verified default-branch entries; binaries local"},
		{Key: "resources", Resolver: "ResourceLimits", Sources: []Source{Run, Code, Default}, Phase: AcceptPlan, Merge: "per_dimension", Zero: "invalid", Validation: "positive finite cores and memory; every explicit dimension checked against operator ceiling"},
		{Key: "source", Resolver: "SourceRef", Sources: []Source{Run, ProjectPipeline, Code, Default}, Phase: AcceptPlan, Merge: "replace", Zero: "invalid", Validation: "checkout source obeys sealed git facts and operator policy; cannot replace intake SHA"},
		{Key: "token.ttl", Resolver: "TokenTTL", Sources: []Source{Flag, Default}, Phase: Startup, Merge: "replace", Zero: "never_expires", Validation: "zero stays indefinite only for eligible unbound root token; child expiry still bounded by parent/binding"},
		{Key: "run.submit_env_allow", Resolver: "SubmitEnvAllow", Sources: []Source{Run, Machine, Default}, Phase: Intake, Merge: "replace", Zero: "empty list", Validation: "literal names and terminal _* prefix patterns; credentials denied and values masked by procenv"},
		{Key: "operator.owner_execution", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "positive; local has no owner execution deadline"},
		{Key: "operator.max_cores", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "positive finite cores"},
		{Key: "operator.max_memory_bytes", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "positive bytes"},
		{Key: "operator.max_priority", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "valid priority ceiling"},
		{Key: "operator.allowed_admission_classes", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "validated admission classes"},
		{Key: "operator.allowed_sources", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "validated source policies"},
		{Key: "operator.max_concurrent_runners", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative; deployment-wide shared admission"},
		{Key: "operator.max_global_runners", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative; deployment-wide shared admission"},
		{Key: "operator.runner_alarm", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative alarm only"},
		{Key: "operator.max_jobs_per_run", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative; team limit"},
		{Key: "operator.max_global_jobs_per_run", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative global fallback"},
		{Key: "operator.max_runs_per_principal_hour", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative; one deployment-wide guard, max_runs_per_hour is its DB key"},
		{Key: "operator.max_global_runs_per_hour", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative; shared quota reservation"},
		{Key: "operator.min_schedule_interval", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative minimum"},
		{Key: "operator.claims_per_runner_minute", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative per-replica overload protection"},
		{Key: "operator.heartbeats_per_runner_minute", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative per-replica overload protection"},
		{Key: "operator.requests_per_token_minute", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative per-replica overload protection"},
		{Key: "operator.requests_per_minute_alarm", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative per-replica alarm"},
		{Key: "operator.max_log_streams_per_principal", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative per-replica protection; logs excluded from download cap"},
		{Key: "operator.max_downloads_per_principal", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative per-replica protection"},
		{Key: "operator.shed_queue_depth", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative per-replica protection"},
		{Key: "operator.egress_daily_alarm_bytes", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "nonnegative deployment usage alarm; additive replica counters"},
		{Key: "operator.enforce_idle_claim_poll", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "boolean enforcement policy"},
		{Key: "operator.max_claim_wait", Resolver: "ControllerCeilings", Sources: OperatorPrecedence(), Phase: Startup, Merge: "replace", Zero: "setting_specific", Validation: "positive duration"},
	}
}
